param([string]$Version='1.0.0-rc.5',[Parameter(Mandatory=$true)][string]$PythonRuntimeRoot,[string]$OutputDirectory)
$ErrorActionPreference='Stop';if(!$OutputDirectory){$OutputDirectory=Join-Path $PSScriptRoot 'dist'};$root=Split-Path -Parent (Split-Path -Parent $PSScriptRoot);New-Item -ItemType Directory -Force -Path $OutputDirectory|Out-Null
foreach($service in @(@{Kind='qms';Name='CapstoneQMS';Port=8611;Host='192.0.2.3';Data='qms'},@{Kind='erp';Name='CapstoneERP';Port=8612;Host='192.0.2.4';Data='erp'})){
 $work=Join-Path $PSScriptRoot "work\$($service.Name)-$Version";if(Test-Path $work){Remove-Item -LiteralPath $work -Recurse -Force};New-Item -ItemType Directory -Force -Path "$work\payload\application","$work\payload\data","$work\payload\python-runtime","$work\tools"|Out-Null
 Copy-Item -LiteralPath "$root\services\service_host.py" -Destination "$work\payload\application"
 Copy-Item -LiteralPath "$root\data\$($service.Data)" -Destination "$work\payload\data\$($service.Data)" -Recurse
 if($service.Kind -eq 'qms'){Copy-Item -LiteralPath "$root\data\qms_compatibility.json" -Destination "$work\payload\data\qms\qms_compatibility.json"}
 & robocopy.exe $PythonRuntimeRoot "$work\payload\python-runtime" /E /XD (Join-Path $PythonRuntimeRoot 'Lib\site-packages') '__pycache__' /XF '*.pem' '*.key' '*.pfx' '*.p12' '*.token' '*.secret' /NFL /NDL /NJH /NJS /NP|Out-Null;if($LASTEXITCODE -ge 8){throw 'Runtime copy failed'}
 $tokens=@{SERVICE=$service.Name;KIND=$service.Kind;HOST=$service.Host;HOST_LAST=$service.Host.Split('.')[-1];PORT=[string]$service.Port;VERSION=$Version}
 foreach($template in Get-ChildItem "$PSScriptRoot\templates" -File){$content=Get-Content -Raw $template.FullName;foreach($key in $tokens.Keys){$content=$content.Replace("{{$key}}",$tokens[$key])};$name=$template.Name.Replace('Service',$service.Name);Set-Content -LiteralPath "$work\tools\$name" -Value $content -Encoding utf8}
 $files=Get-ChildItem $work -File -Recurse|Sort-Object FullName;$manifest=[ordered]@{format='capstone-business-service-windows-release-v1';service=$service.Kind;version=$Version;listen="$($service.Host):$($service.Port)";secrets_included=$false;files=@()};foreach($file in $files){$relative=$file.FullName.Substring($work.Length+1).Replace('\','/');$manifest.files+=[ordered]@{path=$relative;sha256=(Get-FileHash $file.FullName -Algorithm SHA256).Hash.ToLowerInvariant();size=$file.Length}};$manifest|ConvertTo-Json -Depth 6|Set-Content "$work\package-manifest.json" -Encoding utf8
 $zip=Join-Path $OutputDirectory "$($service.Name)-$Version-windows-x64.zip";if(Test-Path $zip){Remove-Item $zip -Force};Compress-Archive -Path "$work\*" -DestinationPath $zip;[ordered]@{package=$zip;sha256=(Get-FileHash $zip -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json
}
